"""Independent hand-specified wire/engine histories, including corrupt histories."""
import copy
import json
import pytest
from robustbench.mgpu05.validate import validate, classify_slo

RID='fixture-x'
ENGINE='cmpl-fixture-x-0-1234abcd'
DOMAIN={'host':'cpu-test','boot_id':'test','clock':'CLOCK_MONOTONIC','time_namespace':'test'}


class Tokens:
    def decode(self, ids):
        return ''.join({10:'a',11:'b'}[i] for i in ids)
    def encode(self, text):
        return [{'a':10,'b':11}[c] for c in text]


def fixture(grouped=False):
    # Deliberately not generated by the production replay or scheduler.
    import hashlib
    prompt=[7,8]
    prompt_hash=hashlib.sha256(b'[7,8]').hexdigest()
    metadata={'lssp_schema':'mgpu00-v1','lssp_request_id':RID,'lssp_ordinal':0,
              'lssp_class_id':'tight','lssp_arrival_s':0.,'lssp_deadline_s':30.,'lssp_weight':1.}
    p={'model':'fixture-model','request_id':RID,'prompt':prompt,'max_tokens':2,'vllm_xargs':metadata}
    def event(kind,t,**data):
        return dict(kind=kind,time_s=t,request_id=RID,data=data)
    def chunk(ids,text,finish=None,prompt_ids=None):
        choice=dict(index=0,text=text,token_ids=ids,finish_reason=finish)
        if prompt_ids is not None: choice['prompt_token_ids']=prompt_ids
        return json.dumps(dict(id='cmpl-'+RID,object='text_completion',model='fixture-model',choices=[choice]))
    c=[dict(kind='run_start',time_s=9.9,request_id=None,data=dict(epoch_s=10.,clock_domain=DOMAIN,
        provenance='synthetic_test',requests=[RID],timeout_s=120.)),event('dispatch',10.001),
        event('transport_send',10.002),event('http',10.003,status=200)]
    if grouped:
        c.append(event('sse',10.05,value=chunk([10,11],'ab','length',prompt)))
    else:
        c += [event('sse',10.04,value=chunk([10],'a',prompt_ids=prompt)),
              event('sse',10.05,value=chunk([11],'b','length'))]
    c += [event('sse',10.06,value=json.dumps(dict(id='cmpl-'+RID,object='text_completion',
             model='fixture-model',choices=[],usage=dict(prompt_tokens=2,completion_tokens=2,total_tokens=4)))),
          event('sse',10.07,value='[DONE]'),event('terminal',10.08,state='STREAM_DONE'),
          dict(kind='run_end',time_s=10.09,request_id=None,data=dict(state='FINISHED'))]
    s=[dict(kind='measurement_contract',seq=0,time_s=9.,clock_domain=DOMAIN,provenance='synthetic_test'),
       dict(kind='request_received',seq=1,time_s=10.006,observed_s=10.005,engine_id=ENGINE,request_id=RID,
            metadata=metadata.copy(),prompt_sha256=prompt_hash,prompt_tokens=2,output_limit=2),
       dict(event='admitted',monotonic_s=10.01,engine_id=ENGINE,request_id=RID),
       dict(event='execution_verified',step=1,sampled_tokens={ENGINE:1}),
       dict(kind='runner_tokens',seq=2,time_s=10.021,observed_s=10.02,step=1,token_ids={ENGINE:[10]},request_ids={ENGINE:RID}),
       dict(event='execution_verified',step=2,sampled_tokens={ENGINE:1}),
       dict(kind='runner_tokens',seq=3,time_s=10.031,observed_s=10.03,step=2,token_ids={ENGINE:[11]},request_ids={ENGINE:RID})]
    return [p],c,s


def run(f,tokenizer=None):
    return validate(*f,tokenizer or Tokens(),arrival_duration_s=.2)


def modify_chunk(c, fn, index=0):
    events=[e for e in c if e['kind']=='sse' and e['data']['value']!='[DONE]']
    obj=json.loads(events[index]['data']['value']); fn(obj)
    events[index]['data']['value']=json.dumps(obj)


def test_independent_golden_values():
    r=run(fixture()); row=r['rows'][0]
    assert r['integrity']=='PASS' and r['completed']==1
    assert r['physical_timing']=='NOT_VERIFIED'
    assert row['client_slo']=='PASS' and r['client_slo_goodput_lower']==5
    assert row['client_ttft_s']==pytest.approx(.04)
    assert row['e2e_s']==pytest.approx(.08)
    assert row['client_observed_tpot_s']==pytest.approx(.01)
    assert row['client_inter_token_gaps_s']==pytest.approx([.01])
    assert row['server_queue_s']==pytest.approx(.005)
    assert row['content_transport_consistency']=='PASS'
    assert row['semantic_answer_correctness']==row['numerical_reproducibility']=='NOT_VERIFIED'
    assert row['gpu_generation_times'] is row['http_emission_times'] is row['http_server_receipt_s'] is None


def test_chunk_not_token():
    r=run(fixture(True)); row=r['rows'][0]
    assert r['integrity']=='PASS'
    assert row['client_inter_token_gaps_s'] is None
    assert row['client_slo']=='NOT_VERIFIED'
    assert (r['client_slo_goodput_lower'],r['client_slo_goodput_upper'])==(0,5)


def test_bpe_roundtrip_not_assumed():
    class DifferentEncoding(Tokens):
        def encode(self,text): return [999]
    row=run(fixture(),DifferentEncoding())['rows'][0]
    assert row['state']=='COMPLETED' and row['independent_retokenized_count']==1
    assert row['canonical_retokenization_equal'] is False


@pytest.mark.parametrize('mutation',[
    lambda p,c,s:modify_chunk(c,lambda d:d.update(id='cmpl-other')),
    lambda p,c,s:modify_chunk(c,lambda d:d.update(model='other')),
    lambda p,c,s:modify_chunk(c,lambda d:d.update(object='chat.completion')),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(index=1)),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(token_ids=None)),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(token_ids=[True])),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(text='wrong')),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(prompt_token_ids=[9])),
    lambda p,c,s:modify_chunk(c,lambda d:d['choices'][0].update(finish_reason='stop'),1),
    lambda p,c,s:modify_chunk(c,lambda d:d['usage'].update(completion_tokens=3),2),
    lambda p,c,s:s[1].update(prompt_tokens=3),
    lambda p,c,s:s[1]['metadata'].update(lssp_class_id='medium'),
    lambda p,c,s:s[1].update(engine_id='unbound'),
    lambda p,c,s:s[2].update(engine_id='wrong'),
    lambda p,c,s:s[4]['token_ids'].update({ENGINE:[11]}),
    lambda p,c,s:s[4]['request_ids'].update({ENGINE:'wrong'}),
    lambda p,c,s:s[4].update(observed_s=10.1),
    lambda p,c,s:s[4].update(observed_s=9.),
    lambda p,c,s:s[3]['sampled_tokens'].update({ENGINE:2}),
    lambda p,c,s:s[6].update(step=1),
    lambda p,c,s:s[6].update(seq=4),
    lambda p,c,s:s[0].update(clock_domain={}),
    lambda p,c,s:c.insert(-1,copy.deepcopy(c[-2])),
    lambda p,c,s:c[1].update(time_s=9.99),
    lambda p,c,s:c[2].update(kind='unobserved_transport'),
    lambda p,c,s:c[-3].update(kind='missing_done'),
    lambda p,c,s:c[1].update(request_id='unknown'),
])
def test_corrupt_evidence_fails(mutation):
    p,c,s=fixture(); mutation(p,c,s)
    assert run((p,c,s))['integrity']=='FAIL'


@pytest.mark.parametrize('state',['TIMEOUT','CANCELLED','ERROR','EOF_WITHOUT_DONE','CLIENT_SATURATED','HTTP_ERROR'])
def test_failures_stay_in_denominator(state):
    p,c,s=fixture(); c=c[:3]
    if state=='CLIENT_SATURATED': c=c[:1]
    if state=='HTTP_ERROR': c.append(dict(kind='http',time_s=10.003,request_id=RID,data={'status':500}))
    c.append(dict(kind='terminal',time_s=131. if state=='TIMEOUT' else 10.1,request_id=RID,data={'state':state}))
    r=run((p,c,s[:1]))
    assert r['integrity']=='PASS' and r['completed']==0
    assert r['client_slo_counts']=={'FAIL':1} and r['client_slo_goodput_upper']==0
    assert r['rows'][0]['censoring']=='terminal_failure'


def test_admin_censoring_and_missing_run_end():
    p,c,s=fixture(); r=run((p,c[:3],s[:1]))
    assert r['rows'][0]['state']=='ADMINISTRATIVELY_INCOMPLETE'
    assert r['rows'][0]['client_slo']=='NOT_VERIFIED'
    assert r['evidence_closed']=='NOT_VERIFIED' and r['client_slo_goodput_upper']==5


def test_admin_past_deadline_is_failure():
    p,c,s=fixture(); c=c[:3]+[dict(kind='run_end',time_s=50.,request_id=None,data={'state':'ABORTED'})]
    assert run((p,c,s[:1]))['client_slo_counts']=={'FAIL':1}


def test_client_clock_reversal_rejected():
    p,c,s=fixture(); c[2]['time_s']=9.
    with pytest.raises(ValueError,match='clock'): run((p,c,s))


@pytest.mark.parametrize('first,completion,groups,expected',[
    (11.1,12.,[(11.1,1),(11.2,1)],'FAIL'),
    (10.1,41.,[(10.1,1)],'FAIL'),
    (10.1,11.,[(10.1,1),(10.3,1)],'FAIL'),
    (10.1,11.,[(10.1,1),(10.2,2)],'NOT_VERIFIED'),
    (10.1,11.,[(10.1,1)],'PASS'),
])
def test_slo_thresholds(first,completion,groups,expected):
    assert classify_slo(state='COMPLETED',first_s=first,last_s=groups[-1][0],completion_s=completion,
        arrival_s=10.,deadline_s=40.,observation_groups=groups,ttft_limit=1.,gap_limit=.1,observed_until=42.)==expected


def test_false_timeout_rejected():
    p,c,s=fixture(); c=c[:3]+[dict(kind='terminal',time_s=10.1,request_id=RID,data={'state':'TIMEOUT'})]
    assert run((p,c,s[:1]))['integrity']=='FAIL'


def test_single_output_tpot_undefined():
    p,c,s=fixture(); p[0]['max_tokens']=1; s[1]['output_limit']=1
    s=s[:5]
    modify_chunk(c,lambda d:d['choices'][0].update(finish_reason='length'))
    c.pop(5)
    modify_chunk(c,lambda d:d['usage'].update(completion_tokens=1,total_tokens=3),1)
    r=run((p,c,s))
    assert r['integrity']=='PASS' and r['rows'][0]['client_observed_tpot_s'] is None


def test_partial_response_prefix_checked():
    p,c,s=fixture(); c=c[:5]+[dict(kind='terminal',time_s=131.,request_id=RID,data={'state':'TIMEOUT'})]
    r=run((p,c,s)); assert r['integrity']=='PASS' and r['completed']==0
    modify_chunk(c,lambda d:d['choices'][0].update(token_ids=[11]))
    assert run((p,c,s))['integrity']=='FAIL'


def test_simulated_clock_cannot_gain_physical_label():
    p,c,s=fixture()
    hardware=dict(allocation_kind='FULL_GPU_VERIFIED',node='cpu-test',cuda_device_count=1,
                  devices=[dict(cuda_memory_bytes=80*2**30,mig_device=False,mig_mode_current=0)])
    assert validate(p,c,s,Tokens(),arrival_duration_s=.2,physical_identity=hardware)['physical_timing']=='NOT_VERIFIED'
